    def findOrder(self, numCourses: int, prerequisites: List[List[int]]) -> List[int]:
        graph = {}
        for c in range(numCourses):
            graph[c] = []
        for (cur,prev) in prerequisites:
            graph[cur].append(prev)
        output_path = []
        visit_path = []
        def dfs(cur):
            if cur in visit_path:
                return False
            if cur in output_path:
                return True
            visit_path.append(cur)
            for pre in graph[cur]:
                result = dfs(pre)
                if not result:
                    return False
            visit_path.pop()
            output_path.append(cur)
            return True
        for c in range(numCourses):
            if not dfs(c):
                return []
        return output_path

