    def findOrder(self, numCourses: int, prerequisites: List[List[int]]) -> List[int]:
        # numCourses = 4, prerequisites = [[1,0],[2,0],[3,1],[3,2]]
        graph = collections.defaultdict(list)
        inbounds = [0] * numCourses
        for course, prereq in prerequisites:
            graph[prereq].append(course)
            inbounds[course] += 1

        q = deque()
        visit = set()
        for node, inbound in enumerate(inbounds):
            if inbound == 0:
                q.append(node)
        result = []
        while q:
            node = q.popleft()
            # if node in visit:
            #     return []
            visit.add(node)
            result.append(node)
            for child in graph[node]:
                inbounds[child] -= 1
                if inbounds[child] == 0:
                    q.append(child)
        return result if len(visit) == numCourses else []

