        :type nums: List[int]
        :type k: int
        :rtype: List[int]
        """

        freq_dict = {}

        if len(nums) == 1:
            return nums

        for num in nums:
            if num not in freq_dict.keys():
                freq_dict[num] = 1
            else:
                freq_dict[num] += 1

        most_freq = []
        sorted_list = sorted(freq_dict.items(),key=lambda x : x[1],reverse=True)

