            if k != 0:
                most_freq.append(item[0])
                k -= 1

        return most_freq

class Solution(object):
    def topKFrequent(self, nums, k):

        def lookForSmallestValue(list,hashmap):
            smallestValueForKey = 10001
            index = len(list)
            for x,y in enumerate(reversed(list)):
                reversedIndex = len(list) - x - 1
                if y == 10001:
                    return reversedIndex
                if hashmap[y] < smallestValueForKey:
                    smallestValueForKey = hashmap[y]
                    index = reversedIndex
            return index

        hashMap = {}
        res = [10001] * k
        for y in nums:
            if y in hashMap:
                hashMap[y] += 1
            else:
                hashMap[y] = 1
        for key in hashMap:
            smallest = lookForSmallestValue(res,hashMap)
            if res[smallest] in hashMap:
                if hashMap[res[smallest]] < hashMap[key]:
                    res[smallest] = key
            else:
                res[smallest] = key
        return res

