class Solution:
    def findKthLargest(self, nums: List[int], k: int) -> int:
        # heap sort
        # 找第k大的数，可以建立一个大小为k的min heap: 堆顶即为所求，堆顶的数比下面k-1个数都小，所以是第k大的数
        self.min_heap = [None]
        res = self.find_top_k(nums,k)
        return res

    def find_top_k(self, array, k):
        for num in array:
            size = len(self.min_heap) - 1
            if size <k:
                self.min_heap.append(num)
                self.swim(size+1)
            else:
                if num > self. min_heap[1]:
                    self.min_heap[1] = num
                    self.sink(1, size)
        return self.min_heap[1]

    def swim(self, i):
        while i > 1 and self.min_heap[i//2] > self.min_heap[i]:
            # 父节点比它大，上浮
            self.min_heap[i//2], self.min_heap[i] = self.min_heap[i], self.min_heap[i//2]
            i = i//2

    def sink(self,i,n):
        while i * 2 <= n:
            j = i*2
            if j + 1 <= n and self.min_heap[j + 1] < self.min_heap[j]:
                j = i*2 + 1
            if self.min_heap[j] >= self.min_heap[i]:
                break
            self.min_heap[j], self.min_heap[i] = self.min_heap[i], self.min_heap[j]
            i = j

