class Solution(object):
    def networkDelayTime(self, times, n, k):
        """
        :type times: List[List[int]]
        :type n: int
        :type k: int
        :rtype: int
        """

        adjacencyList = {}

        for time in times:
            if time[0] not in adjacencyList:
                adjacencyList[time[0]] = [[time[2], time[1]]]
            else:
                adjacencyList[time[0]].append([time[2], time[1]])

        import heapq
        queue = []
        heapq.heappush(queue, [0,k])
        visited = [False]*(n+1)
        distances = [float('inf')]*(n+1)
        distances[0] = 0
        distances[k] = 0

        while queue:
            curr = heapq.heappop(queue)
            dist = curr[0]
            node = curr[1]
            visited[node] = True

            if distances[node] > dist:
                distances[node] = dist

            if node in adjacencyList:
                for n in adjacencyList[node]:
                    if not visited[n[1]]:
                        heapq.heappush(queue, [n[0] + dist, n[1]])

        minTime = max(distances)

        if minTime == float('inf'):
            return -1
        else:
            return minTime

import sys
class Solution(object):
    def networkDelayTime(self, times, n, k):
        """
        :type times: List[List[int]]
        :type n: int
        :type k: int
        :rtype: int
        """


        # times = [[2,1,1],[2,3,1],[3,4,1]]; n = 4; k = 2
        start_node = k

        edges = {}

        counter = 0
        while counter < len(times):
            edges[(times[counter][0], times[counter][1])] = times[counter][2]
            counter += 1



        nodes = {} # this tells us the shortest distance to reach each node from the start node

        counter = 1
        while counter <= n:
            if counter == start_node:
                nodes[counter] = 0
            else:
                nodes[counter] = sys.maxsize
            counter += 1

        counter = 1

        while counter < n:

            for edge in edges:

                start = edge[0]
                end = edge[1]

                if nodes[start] != sys.maxsize:

                    weight = nodes[start] + edges[edge]

                    if weight < nodes[end]:
                        nodes[end] = weight
            counter += 1

        mx = 0

        for key in nodes:
            if nodes[key] > mx:
