        def binary_search(nums, target, find_start):
            index = -1
            l, r = 0, len(nums) - 1
            while l <= r:
                mid = l + (r - l) // 2
                if nums[mid] == target:
                    index = mid
                    if find_start:
                        r = mid - 1 
                    else:
                        l = mid + 1 
                elif nums[mid] < target:
                    l = mid + 1
                else:
                    r = mid - 1
            return index
        start = binary_search(nums, target, find_start=True)
        end = binary_search(nums, target, find_start=False)
