class Solution:
    def searchRange(self, nums: List[int], target: int) -> List[int]:
        return [self.find_first(nums, target), self.find_last(nums, target)]

    def find_first(self, nums, target):
        if len(nums) == 0:
            return -1
        ll = 0
        rr = len(nums) - 1
        while ll < rr:
            mm = (ll + rr) // 2
            if target <= nums[mm]:
                rr = mm
            else:
                ll = mm + 1

        return ll if nums[ll] == target else -1

    def find_last(self, nums, target):
        if len(nums) == 0:
            return -1

        ll = 0
        rr = len(nums) - 1
        while ll < rr:
            mm = (ll + rr + 1) // 2
            if target >= nums[mm]:
                ll = mm
            else:
                rr = mm - 1

        return ll if nums[ll] == target else -1

